const fs = require('fs');

// 1. Безопасно разбираем ответ VLM
let visualData = {};
try {
  const content = $('Call VLM (OpenAI-Compatible)').first()?.json?.choices?.[0]?.message?.content || '{}';
  const cleanJson = content.replace(/```json/gi, '').replace(/```/g, '').trim();
  visualData = JSON.parse(cleanJson);
} catch (e) {
  visualData = {};
}

// 2. Находим выбранный диспенсер из SQL
const products = $('Query Products & Prices (SQL)').all().map(item => item.json);
const dispenser = products.find(p => p.category === 'dispenser') || products[0] || {};
const sku = dispenser.sku ? String(dispenser.sku).trim() : '552000';

// 3. Загружаем изображение диспенсера из смонтированной папки /data/assets/images/
let dispenserBase64 = '';
const searchPaths = [
  `/data/assets/images/${sku}.png`,
  `/data/assets/images/${sku}.jpg`,
  '/data/assets/images/552000.png'
];

for (const p of searchPaths) {
  try {
    if (fs.existsSync(p)) {
      dispenserBase64 = fs.readFileSync(p).toString('base64');
      if (dispenserBase64) break;
    }
  } catch (err) {}
}

const userPhotoBase64 = $('Prepare VLM & Session').first()?.json?.photo_base64 || '';
const placement = visualData.placement_instruction_en || 'Mount the dispenser on the wall to the side of the sink counter at eye level';
const dims = dispenser.dimensions_cm || { w: 33.7, h: 37.2 };

return [{
  json: {
    dispenser,
    dispenser_sku: sku,
    dispenser_name: dispenser.name || 'Диспенсер Tork',
    dispenser_clean_base64: dispenserBase64,
    user_photo_base64: userPhotoBase64,
    placement_instruction_en: placement,
    dimensions_cm: dims,
    recommended_color: visualData.recommended_color || 'white',
    is_valid_washroom: visualData.is_valid_washroom !== false
  }
}];

