parameters.jsCode:
const fs = require('fs');

const products = $('Query Products & Prices (SQL)').all().map(item => item.json);
const session = $('Upsert User Session').first().json || {};
const distributor = products[0] || {};
const visualData = (() => {
  try {
    const raw = $('Call VLM (OpenAI-Compatible)').first().json.choices[0].message.content;
    return JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim());
  } catch (e) {
    return {};
  }
})();

// Извлечение сгенерированного изображения из структуры Google Gemini API
let base64Image = '';
let mimeType = 'image/png';

const parts = $input.first()?.json?.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(p => (p.inlineData && p.inlineData.data) || (p.inline_data && p.inline_data.data));

if (imagePart?.inlineData?.data) {
  base64Image = imagePart.inlineData.data;
  mimeType = imagePart.inlineData.mimeType || 'image/jpeg';
} else if (imagePart?.inline_data?.data) {
  base64Image = imagePart.inline_data.data;
  mimeType = imagePart.inline_data.mime_type || 'image/jpeg';
} else if ($input.first()?.json?.data?.[0]?.b64_json) {
  base64Image = $input.first().json.data[0].b64_json;
} else if ($input.first()?.json?.rendered_image_base64) {
  base64Image = $input.first().json.rendered_image_base64;
}

// Надежный fallback: если API генерации не вернуло фото, берем оригинальное фото подобранного диспенсера Tork
const mainDispenser = products.find(p => p.category === 'dispenser') || products[0] || {};
const sku = mainDispenser.sku ? String(mainDispenser.sku).trim() : '552000';

if (!base64Image) {
  const fallbackPaths = [
    `/data/assets/images/${sku}.png`,
    `/data/assets/images/${sku}.jpg`,
    '/data/assets/images/552000.png'
  ];
  for (const fp of fallbackPaths) {
    try {
      if (fs.existsSync(fp)) {
        base64Image = fs.readFileSync(fp).toString('base64');
        mimeType = 'image/png';
        if (base64Image) break;
      }
    } catch (e) {}
  }
}

let rowsHtml = '';
let totalSum = 0;
let rowIdx = 1;

for (const prod of products) {
  if (!prod.sku) continue;
  const qty = prod.category === 'dispenser'
    ? 1
    : Math.ceil(((session.daily_traffic || 100) * 30 * (prod.refill_norms?.daily_use_per_person || 2)) / (prod.refill_norms?.portions_per_unit || 1000));

  const linePrice = Number(prod.current_price_kzt || prod.price || 0);
  const lineSum = linePrice * qty;
  totalSum += lineSum;

  const imgUrl = prod.image_url || `http://cdn/images/${prod.sku}.png`;
  const imgHtml = `<img src="${imgUrl}" width="34" height="34" style="object-fit:contain; vertical-align:middle; margin-right:8px; border-radius:3px; border:1px solid #E2E8F0; background:#fff;" />`;

  rowsHtml += `
    <tr>
      <td class="text-center">${rowIdx++}</td>
      <td><strong>${prod.sku}</strong></td>
      <td><div style="display:flex; align-items:center;">${imgHtml}<span>${prod.name || 'Продукция Tork'}</span></div></td>
      <td class="text-center"><span class="badge">${prod.system_code || 'H1'}</span></td>
      <td class="text-center">${qty}</td>
      <td class="text-right">${linePrice.toLocaleString('ru-RU')} ₸</td>
      <td class="text-right"><strong>${lineSum.toLocaleString('ru-RU')} ₸</strong></td>
    </tr>
  `;
}

const colorRu = visualData.recommended_color === 'black' ? 'Черный' : (visualData.recommended_color === 'stainless_steel' ? 'Нержавеющая сталь' : 'Белый');

const tgTrigger = $('Telegram Trigger').first()?.json || {};
const tgUser = tgTrigger.message?.from || tgTrigger.callback_query?.from || {};
const clientName = [tgUser.first_name, tgUser.last_name].filter(Boolean).join(' ') || session.client_name || 'Клиент';
const clientUsername = tgUser.username ? ('@' + tgUser.username) : 'нет';

const managerNotificationText = [
  '🚨 Новая заявка на тест-драйв Tork (Казахстан)',
  '',
  'Клиент: ' + clientName + ' (' + clientUsername + ')',
  'Сегмент: ' + (session.business_segment || 'Коммерческий объект'),
  'Проходимость: ' + (session.daily_traffic || 100) + ' чел/день',
  'Рекомендовано: ' + (mainDispenser.name || 'Диспенсер Tork') + ' (' + colorRu + '), арт. ' + sku,
  'Сумма КП: ' + totalSum.toLocaleString('ru-RU') + ' ₸',
  'Город: ' + (distributor.distributor_city || 'Астана')
].join('\n');

const outputItem = {
  json: {
    total_amount_formatted: totalSum.toLocaleString('ru-RU'),
    total_amount: totalSum,
    table_rows_html: rowsHtml,
    kp_number: 'TKZ-' + Date.now().toString().slice(-6),
    kp_date: new Date().toLocaleDateString('ru-RU'),
    distributor_name: distributor.distributor_name || 'ТОО "Tork Kazakhstan Distribution Astana"',
    distributor_bin: distributor.distributor_bin || '210540032111',
    distributor_city: distributor.distributor_city || 'Астана',
    distributor_address: distributor.distributor_address || 'г. Астана, ул. Достык, 18',
    distributor_phone: distributor.distributor_phone || '+7 (7172) 79-55-01',
    distributor_email: distributor.distributor_email || 'astana@tork-distrib.kz',
    client_name: clientName,
    business_segment: session.business_segment || 'Коммерческий объект',
    daily_traffic: session.daily_traffic || 100,
    dispenser_name: mainDispenser.name || 'Диспенсер Tork',
    dispenser_sku: sku,
    recommended_color_ru: colorRu,
    has_rendered_image: Boolean(base64Image),
    manager_notification_text: managerNotificationText
  }
};

if (base64Image) {
  outputItem.binary = {
    data: {
      data: base64Image,
      mimeType: mimeType,
      fileName: 'tork_visualization.png'
    }
  };
}

return [outputItem];

const binaryObj = $input.first()?.binary;
const propName = binaryObj ? (binaryObj.data ? 'data' : Object.keys(binaryObj)[0]) : null;
let b64 = '';

if (propName) {
  try {
    if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
      const buf = await this.helpers.getBinaryDataBuffer(0, propName);
      if (buf && buf.length > 0) {
        b64 = buf.toString('base64');
      }
    }
  } catch (e) {}

  if (!b64 && binaryObj[propName]?.data && binaryObj[propName].data !== 'filesystem-v2') {
    b64 = binaryObj[propName].data;
  }
}

const mime = (propName && binaryObj[propName]?.mimeType) || 'image/jpeg';
const session = $('Upsert User Session').first().json || {};
return [{
  json: {
    ...session,
    photo_base64: b64,
    photo_base64_url: `data:${mime};base64,${b64}`,
    vlm_model: 'gemini-3.8-flash'
  }
}];
